  flashcards: [
    { front: "Extreme environment", back: "A place where conditions (very hot, cold, dry, high or remote) make it difficult for plants, animals and people to survive." },
    { front: "Adaptation", back: "A feature (structural) or behaviour that helps a living thing survive in its environment." },
    { front: "Desert (definition)", back: "A place receiving less than about 250 mm of precipitation a year — can be hot (Sahara) or cold (Antarctica)." },
    { front: "Transpiration", back: "Loss of water vapour from a plant, mainly through stomata in its leaves." },
    { front: "CAM photosynthesis", back: "Crassulacean Acid Metabolism: cacti open stomata at night to take in carbon dioxide and close them in the heat of the day, saving water." },
    { front: "What is in a camel's hump?", back: "Fat — up to about 35 kg — used for energy. Not water." },
    { front: "Fennec fox ears", back: "Up to about 15 cm long: radiate heat to keep cool and detect prey underground." },
    { front: "Polar bear: fur and skin", back: "Transparent, hollow guard hairs over dense underfur trap air; black skin absorbs heat; blubber up to about 10 cm thick." },
    { front: "Emperor penguin huddle", back: "Behavioural adaptation: thousands huddle and rotate; inside can exceed 20°C when outside is −40°C." },
    { front: "Permafrost", back: "Ground that stays frozen (0°C or below) for at least two consecutive years. The top 'active layer' thaws in summer." },
    { front: "Lichen", back: "A partnership between a fungus (grips rock, holds water) and an alga (photosynthesises). Survives drying and freezing." },
    { front: "Lapse rate", back: "Temperature falls about 6.5°C for every 1,000 m of height gained." },
    { front: "Hypothermia vs heatstroke", back: "Hypothermia: core temperature below 35°C. Heatstroke: core temperature about 40°C or more — cooling system fails." },
    { front: "Altitude sickness", back: "Caused by low oxygen (low air pressure), usually above 2,500 m: headache, nausea, dizziness. Prevent by ascending slowly; cure by descending." },
    { front: "Bedouin tent", back: "Black goat-hair 'house of hair': dense shade, loose weave lets hot air out, fibres swell to shed rain, easy to move by camel." },
    { front: "Sherpa physiology", back: "Studies suggest: better blood flow (more nitric oxide), efficient mitochondria, no overproduction of red blood cells; many carry an EPAS1 gene variant from Tibetan ancestry." },
  ],

